import base64
import io

# We need the Pillow library to easily convert PNG bytes to ICO format.
# Run this in your terminal first: pip install Pillow
from PIL import Image

# Your exact Base64 string
b64_data = b""

png_data = base64.b64decode(b64_data)
image = Image.open(io.BytesIO(png_data))

# Save it as a physical .ico file for PyInstaller to use
image.save("app_icon.ico", format="ICO", sizes=[(96, 96)])
print("Successfully created app_icon.ico!")